typedef long long ll;

typedef struct {
    int n;
    ll *bit;
} Fenwick;

void addFenwick(Fenwick *fw, int idx, ll val) {
    while (idx <= fw->n) {
        fw->bit[idx] += val;
        idx += idx & -idx;
    }
}

ll sumFenwick(Fenwick *fw, int idx) {
    ll s = 0;
    while (idx > 0) {
        s += fw->bit[idx];
        idx -= idx & -idx;
    }
    return s;
}

int main(void) {
    int n, q;
    if (scanf("%d %d", &n, &q) != 2) return 0;

    Fenwick fw;
    fw.n = n;
    fw.bit = (ll *)calloc(n + 1, sizeof(ll));
    if (!fw.bit) return 0;

    for (int k = 0; k < q; k++) {
        int type;
        scanf("%d", &type);

        if (type == 0) {
            int i;
            ll x;
            scanf("%d %lld", &i, &x);
            addFenwick(&fw, i, x);
        } else {
            int s, t;
            scanf("%d %d", &s, &t);
            ll ans = sumFenwick(&fw, t) - sumFenwick(&fw, s - 1);
            printf("%lld\n", ans);
        }
    }

    free(fw.bit);
    return 0;
}

